const oracledb = require('oracledb');
const crypto = require('crypto');
const accountingCore = require('./accounting-core');
const documentCycle = require('./document-cycle-core');
const commercialInvoice = require('./commercial-invoice-core');
const commercialAccounting = require('./commercial-accounting-core');
const businessOperations = require('./business-operations-core');
const receivablesCore = require('./receivables-core');

let pool;
function config() { return { user: process.env.ONYX_DB_USER || 'ONYX_APP', password: process.env.ONYX_DB_PASSWORD, connectString: process.env.ONYX_DB_CONNECT_STRING || '127.0.0.1:1521/XEPDB1', poolMin: 0, poolMax: 4, poolIncrement: 1, stmtCacheSize: 30 }; }
function ensurePassword() { if (!config().password) throw new Error('لم يتم ضبط ONYX_DB_PASSWORD في بيئة التشغيل.'); }
async function getPool() { ensurePassword(); if (!pool) pool = await oracledb.createPool(config()); return pool; }
async function query(sql, binds = {}, options = {}) { const connection = await (await getPool()).getConnection(); try { return await connection.execute(sql, binds, { outFormat: oracledb.OUT_FORMAT_OBJECT, ...options }); } finally { await connection.close(); } }
async function withConnection(work) { const connection = await (await getPool()).getConnection(); try { return await work(connection); } finally { await connection.close(); } }
function dateRange(payload = {}) { const startDate = String(payload.startDate || '1900-01-01').slice(0, 10); const endDate = String(payload.endDate || '2999-12-31').slice(0, 10); if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate) || !/^\d{4}-\d{2}-\d{2}$/.test(endDate) || startDate > endDate) throw new Error('نطاق التاريخ غير صحيح.'); return { startDate, endDate }; }
async function test() { return (await query(`select user as DB_USER, sys_context('USERENV','SERVICE_NAME') as SERVICE_NAME, sys_context('USERENV','DB_NAME') as DB_NAME from dual`)).rows[0]; }
async function dashboard() { try { const [accounts, customers, journals] = await Promise.all([query(`select count(*) as COUNT from ACCOUNT`), query(`select count(*) as COUNT from CUSTOMER`), query(`select count(*) as COUNT from MASTER_JOURNAL_V`)]); return { mode: 'legacy', accounts: accounts.rows[0].COUNT, customers: customers.rows[0].COUNT, journals: journals.rows[0].COUNT }; } catch (_) { const [accounts, companies, entries] = await Promise.all([query(`select count(*) as COUNT from ONYX_ACCOUNT`), query(`select count(*) as COUNT from ONYX_COMPANY`), query(`select count(*) as COUNT from ONYX_JOURNAL_ENTRY`)]); return { mode: 'modern', accounts: accounts.rows[0].COUNT, customers: companies.rows[0].COUNT, journals: entries.rows[0].COUNT }; } }
async function accounts(search = '') { return (await query(`select A_CODE, A_NAME, A_NAME_ENG, A_LEVEL, A_PARENT, DR, INACTIVE_RES from ACCOUNT where (:search is null or upper(A_CODE) like upper(:likeSearch) or upper(A_NAME) like upper(:likeSearch)) order by A_CODE fetch first 250 rows only`, { search: search || null, likeSearch: `%${search}%` })).rows; }
async function customers(search = '') { return (await query(`select C_CODE, C_A_NAME, C_E_NAME, C_PHONE, C_MOBILE, C_E_MAIL, INACTIVE from CUSTOMER where (:search is null or upper(C_CODE) like upper(:likeSearch) or upper(C_A_NAME) like upper(:likeSearch)) order by C_CODE fetch first 250 rows only`, { search: search || null, likeSearch: `%${search}%` })).rows; }
async function journal(limit = 50) { const safeLimit = Math.min(Math.max(Number(limit) || 50, 1), 250); return (await query(`select * from (select * from MASTER_JOURNAL_V order by AD_DATE desc nulls last) where rownum <= :limit`, { limit: safeLimit })).rows; }
async function financialReports(filters = {}) { const { startDate, endDate } = dateRange(filters); return withConnection(async connection => { const ctx = await modernContext(connection); const binds = { company_id: ctx.COMPANY_ID, fiscal_year_id: ctx.FISCAL_YEAR_ID, start_date: startDate, end_date: endDate }; const trialResult = await connection.execute(`select a.account_id, a.account_code, a.account_name_ar, a.account_type, nvl(a.opening_balance,0) opening_balance, nvl(sum(case when e.status_code='POSTED' then l.debit else 0 end),0) total_debit, nvl(sum(case when e.status_code='POSTED' then l.credit else 0 end),0) total_credit from onyx_account a left join onyx_journal_line l on l.account_id=a.account_id left join onyx_journal_entry e on e.entry_id=l.entry_id and e.company_id=:company_id and e.fiscal_year_id=:fiscal_year_id and e.entry_date <= to_date(:end_date,'YYYY-MM-DD') where a.company_id=:company_id group by a.account_id,a.account_code,a.account_name_ar,a.account_type,a.opening_balance order by a.account_code`, binds, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const incomeResult = await connection.execute(`select a.account_type, nvl(sum(l.debit),0) total_debit, nvl(sum(l.credit),0) total_credit from onyx_account a join onyx_journal_line l on l.account_id=a.account_id join onyx_journal_entry e on e.entry_id=l.entry_id where a.company_id=:company_id and e.company_id=:company_id and e.fiscal_year_id=:fiscal_year_id and e.status_code='POSTED' and e.entry_date between to_date(:start_date,'YYYY-MM-DD') and to_date(:end_date,'YYYY-MM-DD') group by a.account_type`, binds, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const invoiceResult = await connection.execute(`select invoice_type, nvl(sum(base_total_amount),0) total_amount, count(*) invoice_count from onyx_invoice where company_id=:company_id and status_code='POSTED' and invoice_date between to_date(:start_date,'YYYY-MM-DD') and to_date(:end_date,'YYYY-MM-DD') group by invoice_type`, binds, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const rows = trialResult.rows.map(row => ({ ...row, BALANCE: Number(row.OPENING_BALANCE || 0) + Number(row.TOTAL_DEBIT || 0) - Number(row.TOTAL_CREDIT || 0) })); const byType = rows.reduce((acc, row) => { const key = String(row.ACCOUNT_TYPE || 'GENERAL').toUpperCase(); acc[key] = (acc[key] || 0) + Number(row.BALANCE || 0); return acc; }, {}); const byIncomeType = incomeResult.rows.reduce((acc, row) => { const key = String(row.ACCOUNT_TYPE || 'GENERAL').toUpperCase(); acc[key] = (acc[key] || 0) + Number(row.TOTAL_CREDIT || 0) - Number(row.TOTAL_DEBIT || 0); return acc; }, {}); const invoices = Object.fromEntries(invoiceResult.rows.map(row => [row.INVOICE_TYPE, { total: Number(row.TOTAL_AMOUNT || 0), count: Number(row.INVOICE_COUNT || 0) }])); const revenue = Math.abs(Number(byIncomeType.REVENUE || byIncomeType.INCOME || 0)); const expenses = Math.abs(Number(byIncomeType.EXPENSE || byIncomeType.COST || byIncomeType.COGS || 0)); const sales = invoices.SALE?.total || 0; const purchases = invoices.PURCHASE?.total || 0; return { context: { companyId: ctx.COMPANY_ID, branchId: ctx.BRANCH_ID, fiscalYearId: ctx.FISCAL_YEAR_ID }, period: { startDate, endDate }, kpis: { revenue: revenue || sales, expenses: expenses || purchases, profit: (revenue || sales) - (expenses || purchases), assets: Math.abs(Number(byType.ASSET || 0)), liabilities: Math.abs(Number(byType.LIABILITY || 0)), equity: Math.abs(Number(byType.EQUITY || 0)), cash: Math.abs(Number(byType.CASH || 0)) }, invoices, trialBalance: rows }; }); }
async function modernAccounts(search = '') { return (await query(`select ACCOUNT_ID, ACCOUNT_CODE, ACCOUNT_NAME_AR, ACCOUNT_NAME_EN, ACCOUNT_TYPE, PARENT_CODE, ACTIVE_FLAG, OPENING_BALANCE from ONYX_ACCOUNT where (:search is null or upper(ACCOUNT_CODE) like upper(:likeSearch) or upper(ACCOUNT_NAME_AR) like upper(:likeSearch)) order by ACCOUNT_CODE fetch first 250 rows only`, { search: search || null, likeSearch: `%${search}%` })).rows; }
async function modernContext(connection, preferred = {}) { const result = await connection.execute(`select c.company_id, b.branch_id, fy.fiscal_year_id from onyx_company c join onyx_branch b on b.company_id=c.company_id join onyx_fiscal_year fy on fy.company_id=c.company_id where c.active_flag=1 and b.active_flag=1 and fy.status_code='OPEN' and (:company_id is null or c.company_id=:company_id) and (:branch_id is null or b.branch_id=:branch_id) and (:fiscal_year_id is null or fy.fiscal_year_id=:fiscal_year_id) fetch first 1 row only`, { company_id: preferred.companyId || null, branch_id: preferred.branchId || null, fiscal_year_id: preferred.fiscalYearId || null }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!result.rows[0]) throw new Error('لا يوجد سياق شركة/فرع/سنة مالية مفتوح.'); return result.rows[0]; }
async function postingRules(preferred = {}) { return withConnection(async connection => { const ctx = await modernContext(connection, preferred); const result = await connection.execute(`select fy.start_date, fy.end_date, fy.status_code, nvl(ac.allow_backdate_flag,0) allow_backdate, nvl(ac.backdate_days_limit,0) backdate_days_limit, nvl(ac.allow_future_date_flag,0) allow_future_date, nvl(ac.current_business_date,trunc(sysdate)) business_date from onyx_fiscal_year fy left join onyx_accounting_control ac on ac.company_id=fy.company_id where fy.fiscal_year_id=:fiscal_year_id`, { fiscal_year_id: ctx.FISCAL_YEAR_ID }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const row = result.rows[0]; if (!row) throw new Error('تعذر قراءة قواعد الترحيل للفترة المالية.'); const iso = value => value instanceof Date ? value.toISOString().slice(0,10) : String(value).slice(0,10); return { context: ctx, period: { status: row.STATUS_CODE, startDate: iso(row.START_DATE), endDate: iso(row.END_DATE), allowBackdate: Number(row.ALLOW_BACKDATE) === 1, backdateDaysLimit: Number(row.BACKDATE_DAYS_LIMIT || 0), allowFutureDate: Number(row.ALLOW_FUTURE_DATE) === 1 }, businessDate: iso(row.BUSINESS_DATE) }; }); }
async function createModernAccount(payload = {}) { const code = String(payload.code || '').trim(); const name = String(payload.name || '').trim(); if (!code || !name) throw new Error('رمز الحساب واسم الحساب مطلوبان.'); return withConnection(async connection => { const ctx = await modernContext(connection); const result = await connection.execute(`insert into ONYX_ACCOUNT(company_id, account_code, account_name_ar, account_type, parent_code, opening_balance) values (:company_id,:code,:name,:type,:parent_code,:opening_balance) returning account_id into :account_id`, { company_id: ctx.COMPANY_ID, code, name, type: payload.type || 'GENERAL', parent_code: payload.parentCode || null, opening_balance: Number(payload.openingBalance || 0), account_id: { dir: oracledb.BIND_OUT, type: oracledb.NUMBER } }, { autoCommit: true }); return { accountId: result.outBinds.account_id[0], code, name }; }); }
async function createModernJournal(payload = {}) { const validated = accountingCore.validateJournal(payload); const lines = await withConnection(async connection => { const resolved = []; for (const line of validated.lines) { let accountId = Number(line.accountId || 0); if (!accountId && line.accountCode) { const account = await connection.execute(`select account_id from ONYX_ACCOUNT where account_code=:code`, { code: String(line.accountCode).trim() }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); accountId = account.rows[0]?.ACCOUNT_ID || 0; } if (!accountId) throw new Error(`الحساب غير موجود: ${line.accountCode || ''}`); resolved.push({ ...line, accountId }); } return resolved; }); return withConnection(async connection => { const ctx = await modernContext(connection); const entryNo = `JV-${Date.now()}`; const entry = await connection.execute(`insert into ONYX_JOURNAL_ENTRY(company_id,branch_id,fiscal_year_id,entry_no,entry_date,description_ar,status_code) values (:company_id,:branch_id,:fiscal_year_id,:entry_no,trunc(sysdate),:description,'DRAFT') returning entry_id into :entry_id`, { ...ctx, entry_no: entryNo, description: validated.description, entry_id: { dir: oracledb.BIND_OUT, type: oracledb.NUMBER } }); const entryId = entry.outBinds.entry_id[0]; for (const line of lines) await connection.execute(`insert into ONYX_JOURNAL_LINE(entry_id,account_id,line_description_ar,debit,credit) values (:entry_id,:account_id,:description,:debit,:credit)`, { entry_id: entryId, account_id: Number(line.accountId), description: line.description || validated.description, debit: Number(line.debit || 0), credit: Number(line.credit || 0) }); await connection.commit(); return { entryId, entryNo, totalDebit: validated.totalDebit, totalCredit: validated.totalCredit, source: validated.source }; }); }
async function modernContacts(search = '') { return (await query(`select contact_id, contact_type, code, name_ar, phone, email, tax_number, credit_limit, active_flag from ONYX_CONTACT where (:search is null or upper(code) like upper(:likeSearch) or upper(name_ar) like upper(:likeSearch)) order by contact_type, code fetch first 250 rows only`, { search: search || null, likeSearch: `%${search}%` })).rows; }
async function modernItems(search = '') { return (await query(`select item_id, item_code, item_name_ar, unit_name, cost_price, sale_price, quantity, reorder_level, active_flag from ONYX_ITEM where (:search is null or upper(item_code) like upper(:likeSearch) or upper(item_name_ar) like upper(:likeSearch)) order by item_code fetch first 250 rows only`, { search: search || null, likeSearch: `%${search}%` })).rows; }
async function createModernContact(payload = {}) { const code = String(payload.code || '').trim(); const name = String(payload.name || '').trim(); const type = payload.type === 'VENDOR' ? 'VENDOR' : 'CUSTOMER'; if (!code || !name) throw new Error('رمز الجهة واسمها مطلوبان.'); return withConnection(async connection => { const ctx = await modernContext(connection); await connection.execute(`insert into ONYX_CONTACT(company_id,contact_type,code,name_ar,phone,email,tax_number) values (:company_id,:type,:code,:name,:phone,:email,:tax_number)`, { company_id: ctx.COMPANY_ID, type, code, name, phone: payload.phone || null, email: payload.email || null, tax_number: payload.taxNumber || null }, { autoCommit: true }); return { code, name, type }; }); }
async function createModernItem(payload = {}) { const code = String(payload.code || '').trim(); const name = String(payload.name || '').trim(); if (!code || !name) throw new Error('رمز الصنف واسمه مطلوبان.'); return withConnection(async connection => { const ctx = await modernContext(connection); await connection.execute(`insert into ONYX_ITEM(company_id,item_code,item_name_ar,unit_name,cost_price,sale_price,quantity,reorder_level) values (:company_id,:code,:name,:unit,:cost,:sale,:quantity,:reorder)`, { company_id: ctx.COMPANY_ID, code, name, unit: payload.unit || 'قطعة', cost: Number(payload.cost || 0), sale: Number(payload.sale || 0), quantity: Number(payload.quantity || 0), reorder: Number(payload.reorder || 0) }, { autoCommit: true }); return { code, name }; }); }
async function createModernInvoice(payload = {}) {
  const type = payload.type === 'PURCHASE' ? 'PURCHASE' : 'SALE';
  const currency = String(payload.currency || 'YER').toUpperCase();
  const exchangeRate = Number(payload.exchangeRate || 1);
  const lines = Array.isArray(payload.lines) ? payload.lines : [];
  const commercial = commercialInvoice.calculateInvoice({ ...payload, type, currency, lines });
  const posting = { ...commercial, lines: commercial.lines.map(line => ({ ...line, lineTotal: line.netAmount, costTotal: line.quantity * line.unitCost })), journal: commercialAccounting.buildInvoiceJournal(commercial, payload), stockMovements: commercial.lines.map(line => ({ itemCode: line.itemCode, quantity: type === 'SALE' ? -line.quantity : line.quantity, unitCost: type === 'SALE' ? line.unitCost : line.unitPrice, movementType: type })) };
  return withConnection(async connection => {
    const ctx = await modernContext(connection, payload.context || {});
    const periodResult = await connection.execute(`select fy.start_date, fy.end_date, fy.status_code, nvl(ac.allow_backdate_flag,0) allow_backdate, nvl(ac.backdate_days_limit,0) backdate_days_limit, nvl(ac.allow_future_date_flag,0) allow_future_date, nvl(ac.current_business_date,trunc(sysdate)) business_date from onyx_fiscal_year fy left join onyx_accounting_control ac on ac.company_id=fy.company_id where fy.fiscal_year_id=:fiscal_year_id`, { fiscal_year_id: ctx.FISCAL_YEAR_ID }, { outFormat: oracledb.OUT_FORMAT_OBJECT });
    const period = periodResult.rows[0];
    if (!period) throw new Error('تعذر قراءة الفترة المالية الحالية.');
    const iso = value => value instanceof Date ? value.toISOString().slice(0, 10) : String(value).slice(0, 10);
    commercialAccounting.validatePeriodForPosting({ period: { status: period.STATUS_CODE, startDate: iso(period.START_DATE), endDate: iso(period.END_DATE), allowBackdate: Number(period.ALLOW_BACKDATE) === 1, backdateDaysLimit: Number(period.BACKDATE_DAYS_LIMIT || 0), allowFutureDate: Number(period.ALLOW_FUTURE_DATE) === 1 }, businessDate: payload.businessDate || iso(period.BUSINESS_DATE), postDate: payload.documentDate || iso(period.BUSINESS_DATE), permissions: payload.permissions || [] });
    let contactId = null;
    if (payload.contactCode) {
      const contact = await connection.execute('select contact_id from ONYX_CONTACT where company_id=:company_id and code=:code and contact_type=:type', { company_id: ctx.COMPANY_ID, code: String(payload.contactCode).trim(), type: type === 'SALE' ? 'CUSTOMER' : 'VENDOR' }, { outFormat: oracledb.OUT_FORMAT_OBJECT });
      contactId = contact.rows[0]?.CONTACT_ID || null;
      if (!contactId) throw new Error('الجهة غير موجودة أو نوعها غير مطابق.');
    }
    const warehouse = await connection.execute('select warehouse_id from ONYX_WAREHOUSE where company_id=:company_id and branch_id=:branch_id and active_flag=1 and (:warehouse_code is null or warehouse_code=:warehouse_code) fetch first 1 row only', { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, warehouse_code: payload.warehouseCode || null }, { outFormat: oracledb.OUT_FORMAT_OBJECT });
    if (!warehouse.rows[0]) throw new Error('لا يوجد مستودع نشط للفرع الحالي.');
    const warehouseId = warehouse.rows[0].WAREHOUSE_ID;
    const invoiceNo = (type === 'SALE' ? 'INV-' : 'PUR-') + Date.now();
    try {
      const invoice = await connection.execute('insert into ONYX_INVOICE(company_id,branch_id,fiscal_year_id,invoice_type,invoice_no,contact_id,invoice_date,subtotal,discount_amount,tax_amount,total_amount,payment_method,paid_amount,outstanding_amount,due_date,status_code,currency_code,exchange_rate,base_subtotal,base_total_amount) values (:company_id,:branch_id,:fiscal_year_id,:type,:invoice_no,:contact_id,to_date(:invoice_date,\'YYYY-MM-DD\'),:subtotal,:discount_amount,:tax_amount,:total,:payment_method,:paid_amount,:outstanding_amount,to_date(:due_date,\'YYYY-MM-DD\'),:status,:currency,:rate,:base_subtotal,:base_total) returning invoice_id into :invoice_id', { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, fiscal_year_id: ctx.FISCAL_YEAR_ID, type, invoice_no: invoiceNo, contact_id: contactId, invoice_date: payload.documentDate || iso(period.BUSINESS_DATE), subtotal: posting.subtotal, discount_amount: posting.invoiceDiscount, tax_amount: posting.taxAmount, total: posting.total, payment_method: posting.paymentMethod, paid_amount: posting.paidAmount, outstanding_amount: posting.outstandingAmount, due_date: payload.dueDate || null, status: 'DRAFT', currency, rate: exchangeRate, base_subtotal: posting.taxableAmount * exchangeRate, base_total: posting.total * exchangeRate, invoice_id: { dir: oracledb.BIND_OUT, type: oracledb.NUMBER } });
      const invoiceId = invoice.outBinds.invoice_id[0];
      for (const line of posting.lines) {
        const item = await connection.execute('select item_id from ONYX_ITEM where company_id=:company_id and item_code=:code for update', { company_id: ctx.COMPANY_ID, code: line.itemCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT });
        if (!item.rows[0]) throw new Error('الصنف غير موجود: ' + line.itemCode);
        await connection.execute('insert into ONYX_INVOICE_LINE(invoice_id,item_id,quantity,unit_price,unit_cost,discount_amount,line_total,base_line_total) values (:invoice_id,:item_id,:quantity,:unit_price,:unit_cost,:discount_amount,:line_total,:base_line_total)', { invoice_id: invoiceId, item_id: item.rows[0].ITEM_ID, quantity: line.quantity, unit_price: line.unitPrice, unit_cost: line.unitCost, discount_amount: line.discountAmount, line_total: line.lineTotal, base_line_total: line.lineTotal * exchangeRate });
      }
      const entry = await connection.execute('insert into ONYX_JOURNAL_ENTRY(company_id,branch_id,fiscal_year_id,entry_no,entry_date,description_ar,status_code,source_code,currency_code,exchange_rate) values (:company_id,:branch_id,:fiscal_year_id,:entry_no,trunc(sysdate),:description,:status,:source,:currency,:rate) returning entry_id into :entry_id', { ...ctx, entry_no: 'JV-' + Date.now(), description: posting.journal.description, status: 'DRAFT', source: posting.journal.source, currency, rate: exchangeRate, entry_id: { dir: oracledb.BIND_OUT, type: oracledb.NUMBER } });
      const entryId = entry.outBinds.entry_id[0];
      for (const line of posting.journal.lines) { const account = await connection.execute('select account_id from ONYX_ACCOUNT where company_id=:company_id and account_code=:code', { company_id: ctx.COMPANY_ID, code: line.accountCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!account.rows[0]) throw new Error('الحساب غير موجود: ' + line.accountCode); await connection.execute('insert into ONYX_JOURNAL_LINE(entry_id,account_id,line_description_ar,debit,credit,foreign_amount,line_currency_code,line_exchange_rate) values (:entry_id,:account_id,:description,:debit,:credit,:foreign_amount,:currency,:rate)', { entry_id: entryId, account_id: account.rows[0].ACCOUNT_ID, description: line.description, debit: line.debit * exchangeRate, credit: line.credit * exchangeRate, foreign_amount: null, currency, rate: exchangeRate }); }
      for (const movement of posting.stockMovements) { const item = await connection.execute('select item_id from ONYX_ITEM where company_id=:company_id and item_code=:code', { company_id: ctx.COMPANY_ID, code: movement.itemCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!item.rows[0]) throw new Error('الصنف غير موجود: ' + movement.itemCode); const delta = movement.quantity; const update = await connection.execute('update ONYX_ITEM set quantity=quantity+:delta where item_id=:item_id and quantity+:delta >= 0', { delta, item_id: item.rows[0].ITEM_ID }); if (update.rowsAffected !== 1) throw new Error('الرصيد المخزني غير كاف للصنف: ' + movement.itemCode); const balance = await connection.execute('update ONYX_ITEM_BALANCE set quantity=quantity+:delta, average_cost=case when quantity+:delta > 0 then ((quantity*average_cost)+(:delta*:unit_cost))/(quantity+:delta) else 0 end, updated_at=systimestamp where warehouse_id=:warehouse_id and item_id=:item_id and quantity+:delta >= 0', { delta, unit_cost: movement.unitCost, warehouse_id: warehouseId, item_id: item.rows[0].ITEM_ID }); if (balance.rowsAffected === 0 && delta < 0) throw new Error('الرصيد المخزني غير كافٍ في المستودع للصنف: ' + movement.itemCode); if (balance.rowsAffected === 0) await connection.execute('insert into ONYX_ITEM_BALANCE(warehouse_id,item_id,quantity,average_cost) values (:warehouse_id,:item_id,:quantity,:average_cost)', { warehouse_id: warehouseId, item_id: item.rows[0].ITEM_ID, quantity: delta, average_cost: movement.unitCost }); await connection.execute('insert into ONYX_STOCK_MOVEMENT(company_id,branch_id,warehouse_id,item_id,invoice_id,movement_type,quantity,unit_cost,movement_date,created_by) values (:company_id,:branch_id,:warehouse_id,:item_id,:invoice_id,:movement_type,:quantity,:unit_cost,to_date(:movement_date,\'YYYY-MM-DD\'),:created_by)', { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, warehouse_id: warehouseId, item_id: item.rows[0].ITEM_ID, invoice_id: invoiceId, movement_type: movement.movementType, quantity: movement.quantity, unit_cost: movement.unitCost, movement_date: payload.documentDate || iso(period.BUSINESS_DATE), created_by: payload.userId || null }); }
      await connection.execute('update ONYX_JOURNAL_ENTRY set status_code=:status, posted_by=:posted_by where entry_id=:entry_id', { status: 'POSTED', posted_by: payload.userId || null, entry_id: entryId });
      await connection.execute('update ONYX_INVOICE set journal_entry_id=:entry_id, status_code=:status, posted_by=:posted_by where invoice_id=:invoice_id', { entry_id: entryId, status: 'POSTED', posted_by: payload.userId || null, invoice_id: invoiceId });
      await connection.commit();
      return { invoiceId, invoiceNo, entryId, type, total: posting.total, baseTotal: posting.total * exchangeRate, stockMovements: posting.stockMovements.length, status: 'POSTED' };
    } catch (error) { await connection.rollback(); throw error; }
  });
}
async function createTradeDocument(payload = {}) { const document = documentCycle.buildTradeDocument(payload); return withConnection(async connection => { const ctx = await modernContext(connection); let contactId = null; let warehouseId = null; if (payload.contactCode) { const contact = await connection.execute('select contact_id from onyx_contact where company_id=:company_id and code=:code', { company_id: ctx.COMPANY_ID, code: document.contactCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); contactId = contact.rows[0]?.CONTACT_ID || null; if (!contactId) throw new Error('الجهة غير موجودة.'); } if (document.warehouseCode) { const warehouse = await connection.execute('select warehouse_id from onyx_warehouse where company_id=:company_id and branch_id=:branch_id and warehouse_code=:code and active_flag=1', { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, code: document.warehouseCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); warehouseId = warehouse.rows[0]?.WAREHOUSE_ID || null; if (!warehouseId) throw new Error('المستودع غير موجود.'); } const docNo = document.documentNo || `${document.documentType.slice(0, 3)}-${Date.now()}`; const inserted = await connection.execute(`insert into onyx_trade_document(company_id,branch_id,fiscal_year_id,warehouse_id,contact_id,source_document_id,document_type,document_no,document_date,currency_code,exchange_rate,subtotal,tax_amount,total_amount,status_code,payment_method,due_date,document_note,created_by) values (:company_id,:branch_id,:fiscal_year_id,:warehouse_id,:contact_id,:source_document_id,:document_type,:document_no,to_date(:document_date,'YYYY-MM-DD'),:currency_code,:exchange_rate,:subtotal,:tax_amount,:total_amount,:status_code,:payment_method,to_date(:due_date,'YYYY-MM-DD'),:document_note,:created_by) returning document_id into :document_id`, { ...ctx, warehouse_id: warehouseId, contact_id: contactId, source_document_id: document.sourceDocumentId, document_type: document.documentType, document_no: docNo, document_date: payload.documentDate || new Date().toISOString().slice(0, 10), currency_code: document.currencyCode, exchange_rate: document.exchangeRate, subtotal: document.subtotal, tax_amount: document.taxAmount, total_amount: document.totalAmount, status_code: document.statusCode, payment_method: payload.paymentMethod || 'CASH', due_date: payload.dueDate || null, document_note: payload.documentNote || null, created_by: payload.userId || null, document_id: { dir: oracledb.BIND_OUT, type: oracledb.NUMBER } }); const documentId = inserted.outBinds.document_id[0]; for (const line of document.lines) { const item = await connection.execute('select item_id from onyx_item where company_id=:company_id and item_code=:item_code', { company_id: ctx.COMPANY_ID, item_code: line.itemCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!item.rows[0]) throw new Error(`الصنف غير موجود: ${line.itemCode}`); await connection.execute(`insert into onyx_trade_document_line(document_id,item_id,source_line_id,quantity,unit_price,tax_amount,line_total) values (:document_id,:item_id,:source_line_id,:quantity,:unit_price,:tax_amount,:line_total)`, { document_id: documentId, item_id: item.rows[0].ITEM_ID, source_line_id: line.sourceLineId, quantity: line.quantity, unit_price: line.unitPrice, tax_amount: line.taxAmount, line_total: line.quantity * line.unitPrice + line.taxAmount }); } if (document.sourceDocumentId) await connection.execute('insert into onyx_document_link(parent_document_id,child_document_id,linked_by) values (:parent_document_id,:child_document_id,:linked_by)', { parent_document_id: document.sourceDocumentId, child_document_id: documentId, linked_by: payload.userId || null }); await connection.commit(); return { documentId, documentNo: docNo, documentType: document.documentType, statusCode: document.statusCode, totalAmount: document.totalAmount }; }); }
async function listTradeDocuments(filters = {}) { const limit = Math.min(Math.max(Number(filters.limit) || 100, 1), 500); return withConnection(async connection => { const ctx = await modernContext(connection); return (await connection.execute(`select * from (select document_id,company_id,branch_id,contact_id,warehouse_id,source_document_id,document_type,document_no,document_date,currency_code,exchange_rate,subtotal,tax_amount,total_amount,status_code,created_by,approved_by,posted_by,created_at,approved_at,posted_at from onyx_trade_document where company_id=:company_id and branch_id=:branch_id and (fiscal_year_id=:fiscal_year_id or fiscal_year_id is null) and (:document_type is null or document_type=:document_type) and (:status_code is null or status_code=:status_code) and document_date between to_date(:start_date,'YYYY-MM-DD') and to_date(:end_date,'YYYY-MM-DD') order by document_date desc,document_id desc) where rownum <= :limit`, { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, fiscal_year_id: ctx.FISCAL_YEAR_ID, document_type: filters.documentType || null, status_code: filters.statusCode || null, start_date: filters.startDate || '1900-01-01', end_date: filters.endDate || '2999-12-31', limit }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; }); }
async function transitionTradeDocument(payload = {}) { const current = String(payload.currentStatus || '').toUpperCase(); const next = String(payload.nextStatus || '').toUpperCase(); documentCycle.validateTransition(current, next); return withConnection(async connection => { const result = await connection.execute('update onyx_trade_document set status_code=:next_status, approved_by=case when :next_status=\'APPROVED\' then :user_id else approved_by end, approved_at=case when :next_status=\'APPROVED\' then systimestamp else approved_at end, posted_by=case when :next_status=\'POSTED\' then :user_id else posted_by end where document_id=:document_id and status_code=:current_status', { next_status: next, user_id: payload.userId || null, document_id: Number(payload.documentId), current_status: current }); if (result.rowsAffected !== 1) throw new Error('المستند غير موجود أو تغيرت حالته.'); await connection.execute(`insert into onyx_audit_log(user_id,company_id,branch_id,action_code,entity_type,entity_id,before_value,after_value,terminal_name) select :user_id,company_id,branch_id,'DOCUMENT_STATUS_CHANGE','TRADE_DOCUMENT',to_char(document_id),:before_value,:after_value,'Electron' from onyx_trade_document where document_id=:document_id`, { user_id: payload.userId || null, before_value: JSON.stringify({ statusCode: current }), after_value: JSON.stringify({ statusCode: next }), document_id: Number(payload.documentId) }); await connection.commit(); return { documentId: Number(payload.documentId), statusCode: next }; }); }
function hashPassword(password) { const iterations = 210000; const salt = crypto.randomBytes(16).toString('base64url'); const hash = crypto.pbkdf2Sync(String(password), salt, iterations, 32, 'sha256').toString('base64url'); return `pbkdf2$${iterations}$${salt}$${hash}`; }
function verifyPassword(password, stored) { const [algorithm, iterations, salt, expected] = String(stored || '').split('$'); if (algorithm !== 'pbkdf2' || !iterations || !salt || !expected) return false; const actual = crypto.pbkdf2Sync(String(password), salt, Number(iterations), 32, 'sha256').toString('base64url'); return crypto.timingSafeEqual(Buffer.from(actual), Buffer.from(expected)); }
async function authenticate(username, password, context = {}) { const name = String(username || '').trim().toUpperCase(); return withConnection(async connection => { const found = await connection.execute(`select user_id, username, display_name_ar, password_hash, language_code, active_flag, locked_until, failed_attempts from onyx_user where upper(username)=:username`, { username: name }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const user = found.rows[0]; const fail = async (reason) => { if (user) { const attempts = Number(user.FAILED_ATTEMPTS || 0) + 1; const lock = attempts >= 5 ? new Date(Date.now() + 15 * 60 * 1000) : null; await connection.execute(`update onyx_user set failed_attempts=:attempts, locked_until=:locked_until where user_id=:user_id`, { attempts, locked_until: lock, user_id: user.USER_ID }); } await connection.execute(`insert into onyx_login_history(user_id,username_entered,company_id,branch_id,fiscal_year_id,language_code,terminal_name,login_type,failure_reason) values (:user_id,:username,:company_id,:branch_id,:fiscal_year_id,:language_code,:terminal,'FAILURE',:reason)`, { user_id: user?.USER_ID || null, username: name, company_id: context.companyId || null, branch_id: context.branchId || null, fiscal_year_id: context.fiscalYearId || null, language_code: context.languageCode || 'ar', terminal: context.terminal || 'Electron', reason }); await connection.commit(); throw new Error('بيانات الدخول غير صحيحة أو الحساب مقفل.'); }; if (!user || Number(user.ACTIVE_FLAG) !== 1) return fail('INVALID_USER'); if (user.LOCKED_UNTIL && new Date(user.LOCKED_UNTIL).getTime() > Date.now()) return fail('LOCKED'); if (!verifyPassword(password, user.PASSWORD_HASH)) return fail('INVALID_PASSWORD'); const permissionRows = await connection.execute(`select distinct p.permission_code from onyx_user_role ur join onyx_role_permission rp on rp.role_id=ur.role_id join onyx_permission p on p.permission_id=rp.permission_id where ur.user_id=:user_id`, { user_id: user.USER_ID }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const roles = await connection.execute(`select r.role_code, r.role_name_ar from onyx_user_role ur join onyx_role r on r.role_id=ur.role_id where ur.user_id=:user_id`, { user_id: user.USER_ID }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); await connection.execute(`update onyx_user set failed_attempts=0, locked_until=null, last_login_at=systimestamp where user_id=:user_id`, { user_id: user.USER_ID }); await connection.execute(`insert into onyx_login_history(user_id,username_entered,company_id,branch_id,fiscal_year_id,language_code,terminal_name,login_type) values (:user_id,:username,:company_id,:branch_id,:fiscal_year_id,:language_code,:terminal,'SUCCESS')`, { user_id: user.USER_ID, username: name, company_id: context.companyId || null, branch_id: context.branchId || null, fiscal_year_id: context.fiscalYearId || null, language_code: context.languageCode || user.LANGUAGE_CODE, terminal: context.terminal || 'Electron' }); await connection.commit(); return { userId: user.USER_ID, username: user.USERNAME, displayNameAr: user.DISPLAY_NAME_AR, languageCode: user.LANGUAGE_CODE, permissions: permissionRows.rows.map(x => x.PERMISSION_CODE), roles: roles.rows }; }); }
async function createUser(payload = {}) { const username = String(payload.username || '').trim().toUpperCase(); const displayName = String(payload.displayNameAr || '').trim(); const password = String(payload.password || ''); if (!username || !displayName || password.length < 8) throw new Error('اسم المستخدم والاسم وكلمة مرور من 8 أحرف مطلوبة.'); return withConnection(async connection => { const result = await connection.execute(`insert into onyx_user(username,display_name_ar,password_hash,language_code) values (:username,:display_name,:password_hash,:language_code) returning user_id into :user_id`, { username, display_name: displayName, password_hash: hashPassword(password), language_code: payload.languageCode || 'ar', user_id: { dir: oracledb.BIND_OUT, type: oracledb.NUMBER } }); await connection.commit(); return { userId: result.outBinds.user_id[0], username, displayNameAr: displayName }; }); }
async function listUsers() { return (await query(`select user_id, username, display_name_ar, language_code, active_flag, failed_attempts, locked_until, last_login_at, created_at from onyx_user order by username`)).rows; }
async function listRoles() { return (await query(`select role_id, role_code, role_name_ar, active_flag from onyx_role order by role_code`)).rows; }
async function assignRole(userId, roleCode) { return withConnection(async connection => { const role = await connection.execute(`select role_id from onyx_role where role_code=:role_code`, { role_code: String(roleCode).toUpperCase() }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!role.rows[0]) throw new Error('الدور غير موجود.'); await connection.execute(`merge into onyx_user_role x using dual on (x.user_id=:user_id and x.role_id=:role_id) when not matched then insert(user_id,role_id) values(:user_id,:role_id)`, { user_id: Number(userId), role_id: role.rows[0].ROLE_ID }); await connection.commit(); return { userId: Number(userId), roleCode: String(roleCode).toUpperCase() }; }); }
async function listSessionContexts(userId) { const id = Number(userId); if (!Number.isInteger(id) || id <= 0) throw new Error('المستخدم غير صالح.'); return (await query(`select s.company_id, c.company_code, c.company_name_ar, s.branch_id, b.branch_code, b.branch_name_ar, fy.fiscal_year_id, fy.fiscal_year, fy.start_date, fy.end_date, fy.status_code from onyx_user_scope s join onyx_company c on c.company_id=s.company_id and c.active_flag=1 join onyx_branch b on b.branch_id=s.branch_id and b.company_id=s.company_id and b.active_flag=1 join onyx_fiscal_year fy on fy.fiscal_year_id=nvl(s.default_year_id, fy.fiscal_year_id) and fy.company_id=s.company_id where s.user_id=:user_id and fy.status_code='OPEN' order by c.company_code,b.branch_code,fy.fiscal_year`, { user_id: id })).rows; }
async function setSessionContext(userId, payload = {}) { const ids = { user_id: Number(userId), company_id: Number(payload.companyId), branch_id: Number(payload.branchId), fiscal_year_id: Number(payload.fiscalYearId) }; if (!Object.values(ids).every(value => Number.isInteger(value) && value > 0)) throw new Error('يجب اختيار شركة وفرع وسنة مالية.'); return withConnection(async connection => { const result = await connection.execute(`select c.company_id, c.company_code, c.company_name_ar, b.branch_id, b.branch_code, b.branch_name_ar, fy.fiscal_year_id, fy.fiscal_year, fy.start_date, fy.end_date, fy.status_code from onyx_user_scope s join onyx_company c on c.company_id=s.company_id and c.active_flag=1 join onyx_branch b on b.branch_id=s.branch_id and b.company_id=s.company_id and b.active_flag=1 join onyx_fiscal_year fy on fy.fiscal_year_id=:fiscal_year_id and fy.company_id=s.company_id and fy.status_code='OPEN' where s.user_id=:user_id and s.company_id=:company_id and s.branch_id=:branch_id`, ids, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!result.rows[0]) throw new Error('السياق المختار غير متاح لهذا المستخدم أو السنة المالية مغلقة.'); return result.rows[0]; }); }
async function recordAudit(payload = {}) { return withConnection(async connection => { await connection.execute(`insert into onyx_audit_log(user_id,company_id,branch_id,fiscal_year_id,action_code,entity_type,entity_id,before_value,after_value,reason,terminal_name) values (:user_id,:company_id,:branch_id,:fiscal_year_id,:action_code,:entity_type,:entity_id,:before_value,:after_value,:reason,:terminal_name)`, { user_id: payload.userId || null, company_id: payload.companyId || null, branch_id: payload.branchId || null, fiscal_year_id: payload.fiscalYearId || null, action_code: String(payload.actionCode || '').toUpperCase(), entity_type: String(payload.entityType || '').toUpperCase(), entity_id: payload.entityId == null ? null : String(payload.entityId), before_value: payload.beforeValue == null ? null : (typeof payload.beforeValue === 'string' ? payload.beforeValue : JSON.stringify(payload.beforeValue)), after_value: payload.afterValue == null ? null : (typeof payload.afterValue === 'string' ? payload.afterValue : JSON.stringify(payload.afterValue)), reason: payload.reason || null, terminal_name: payload.terminal || 'Electron' }); await connection.commit(); return true; }); }
async function listAudit(payload = {}) { const { startDate, endDate } = dateRange(payload); const limit = Math.min(Math.max(Number(payload.limit) || 100, 1), 500); return (await query(`select * from (select a.audit_id,a.user_id,u.username,u.display_name_ar,a.company_id,a.branch_id,a.fiscal_year_id,a.action_code,a.entity_type,a.entity_id,a.before_value before_json,a.after_value after_json,a.reason,a.terminal_name,a.created_at from onyx_audit_log a left join onyx_user u on u.user_id=a.user_id where (:company_id is null or a.company_id=:company_id) and (:branch_id is null or a.branch_id=:branch_id) and (:entity_type is null or a.entity_type=:entity_type) and a.created_at >= to_date(:start_date,'YYYY-MM-DD') and a.created_at < to_date(:end_date,'YYYY-MM-DD') + 1 order by a.created_at desc) where rownum <= :limit`, { company_id: payload.companyId || null, branch_id: payload.branchId || null, entity_type: payload.entityType || null, start_date: startDate, end_date: endDate, limit })).rows; }
async function createCashVoucher(payload = {}) { const voucher = businessOperations.buildVoucher(payload); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const no = voucher.voucherNo || `${voucher.voucherType.slice(0, 3)}-${Date.now()}`; const cash = await connection.execute('select account_id from onyx_account where company_id=:company_id and account_code=:code and active_flag=1', { company_id: ctx.COMPANY_ID, code: voucher.cashAccountCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!cash.rows[0]) throw new Error(`حساب الصندوق أو البنك غير موجود: ${voucher.cashAccountCode}`); const inserted = await connection.execute(`insert into onyx_cash_voucher(company_id,branch_id,fiscal_year_id,voucher_type,voucher_no,voucher_date,cash_account_id,total_amount,status_code,description_ar,created_by) values (:company_id,:branch_id,:fiscal_year_id,:voucher_type,:voucher_no,to_date(:voucher_date,'YYYY-MM-DD'),:cash_account_id,:total_amount,'DRAFT',:description,:created_by) returning voucher_id into :voucher_id`, { ...ctx, voucher_type: voucher.voucherType, voucher_no: no, voucher_date: payload.voucherDate || new Date().toISOString().slice(0, 10), cash_account_id: cash.rows[0].ACCOUNT_ID, total_amount: voucher.total, description: voucher.journal.description, created_by: payload.userId || null, voucher_id: { dir: oracledb.BIND_OUT, type: oracledb.NUMBER } }); const voucherId = inserted.outBinds.voucher_id[0]; for (const line of voucher.lines) { const account = await connection.execute('select account_id from onyx_account where company_id=:company_id and account_code=:code and active_flag=1', { company_id: ctx.COMPANY_ID, code: line.accountCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!account.rows[0]) throw new Error(`الحساب غير موجود: ${line.accountCode}`); await connection.execute('insert into onyx_cash_voucher_line(voucher_id,account_id,amount,line_description_ar) values (:voucher_id,:account_id,:amount,:description)', { voucher_id: voucherId, account_id: account.rows[0].ACCOUNT_ID, amount: line.amount, description: line.description || voucher.journal.description }); } await connection.commit(); return { voucherId, voucherNo: no, voucherType: voucher.voucherType, total: voucher.total, status: 'DRAFT' }; }); }
async function listCashVouchers(payload = {}) { const limit = Math.min(Math.max(Number(payload.limit) || 100, 1), 500); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); return (await connection.execute(`select * from (select v.voucher_id,v.voucher_no,v.voucher_type,v.voucher_date,v.total_amount,v.status_code,v.description_ar,a.account_code cash_account_code,a.account_name_ar cash_account_name from onyx_cash_voucher v join onyx_account a on a.account_id=v.cash_account_id where v.company_id=:company_id and v.branch_id=:branch_id and (:fiscal_year_id is null or v.fiscal_year_id=:fiscal_year_id) and (:voucher_type is null or v.voucher_type=:voucher_type) order by v.voucher_date desc,v.voucher_id desc) where rownum <= :limit`, { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, fiscal_year_id: ctx.FISCAL_YEAR_ID || null, voucher_type: payload.voucherType || null, limit }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; }); }
async function updateCashVoucher(payload = {}) { const voucherId = Number(payload.voucherId); if (!Number.isInteger(voucherId) || voucherId <= 0) throw new Error('رقم السند غير صالح.'); const voucher = businessOperations.buildVoucher(payload); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const existing = await connection.execute('select status_code from onyx_cash_voucher where voucher_id=:voucher_id and company_id=:company_id and branch_id=:branch_id for update', { voucher_id: voucherId, company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!existing.rows[0]) throw new Error('السند غير موجود.'); if (existing.rows[0].STATUS_CODE !== 'DRAFT') throw new Error('لا يمكن تعديل سند مرحّل؛ استخدم الإلغاء ثم أنشئ سندًا بديلًا.'); const cash = await connection.execute('select account_id from onyx_account where company_id=:company_id and account_code=:code and active_flag=1', { company_id: ctx.COMPANY_ID, code: voucher.cashAccountCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!cash.rows[0]) throw new Error(`حساب الصندوق أو البنك غير موجود: ${voucher.cashAccountCode}`); await connection.execute(`update onyx_cash_voucher set voucher_type=:voucher_type,voucher_date=to_date(:voucher_date,'YYYY-MM-DD'),cash_account_id=:cash_account_id,total_amount=:total_amount,description_ar=:description where voucher_id=:voucher_id`, { voucher_type: voucher.voucherType, voucher_date: payload.voucherDate || new Date().toISOString().slice(0, 10), cash_account_id: cash.rows[0].ACCOUNT_ID, total_amount: voucher.total, description: voucher.journal.description, voucher_id: voucherId }); await connection.execute('delete from onyx_cash_voucher_line where voucher_id=:voucher_id', { voucher_id: voucherId }); for (const line of voucher.lines) { const account = await connection.execute('select account_id from onyx_account where company_id=:company_id and account_code=:code and active_flag=1', { company_id: ctx.COMPANY_ID, code: line.accountCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!account.rows[0]) throw new Error(`الحساب غير موجود: ${line.accountCode}`); await connection.execute('insert into onyx_cash_voucher_line(voucher_id,account_id,amount,line_description_ar) values (:voucher_id,:account_id,:amount,:description)', { voucher_id: voucherId, account_id: account.rows[0].ACCOUNT_ID, amount: line.amount, description: line.description || voucher.journal.description }); } await connection.commit(); return { voucherId, total: voucher.total, status: 'DRAFT' }; }); }
async function voidCashVoucher(payload = {}) { const voucherId = Number(payload.voucherId); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const result = await connection.execute(`update onyx_cash_voucher set status_code='VOID' where voucher_id=:voucher_id and company_id=:company_id and branch_id=:branch_id and status_code<>'VOID'`, { voucher_id: voucherId, company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID }); if (result.rowsAffected !== 1) throw new Error('السند غير موجود أو ملغى مسبقًا.'); await connection.commit(); return { voucherId, status: 'VOID' }; }); }
async function createExpenseIncome(payload = {}) { const operationType = String(payload.operationType || 'EXPENSE').toUpperCase(); const operation = operationType === 'INCOME' ? businessOperations.buildIncome(payload) : businessOperations.buildExpense(payload); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const cash = await connection.execute('select account_id from onyx_account where company_id=:company_id and account_code=:code and active_flag=1', { company_id: ctx.COMPANY_ID, code: payload.cashAccountCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const categoryCode = operationType === 'INCOME' ? payload.incomeAccountCode : payload.expenseAccountCode; const category = await connection.execute('select account_id from onyx_account where company_id=:company_id and account_code=:code and active_flag=1', { company_id: ctx.COMPANY_ID, code: categoryCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!cash.rows[0] || !category.rows[0]) throw new Error('حساب الصندوق أو الحساب التصنيفي غير موجود.'); const no = payload.operationNo || `${operationType.slice(0, 3)}-${Date.now()}`; const inserted = await connection.execute(`insert into onyx_expense_income(company_id,branch_id,fiscal_year_id,operation_type,operation_no,operation_date,description_ar,amount,cash_account_id,category_account_id,status_code,created_by) values (:company_id,:branch_id,:fiscal_year_id,:operation_type,:operation_no,to_date(:operation_date,'YYYY-MM-DD'),:description,:amount,:cash_account_id,:category_account_id,'DRAFT',:created_by) returning operation_id into :operation_id`, { ...ctx, operation_type: operationType, operation_no: no, operation_date: payload.operationDate || new Date().toISOString().slice(0, 10), description: operation.description, amount: operation.total, cash_account_id: cash.rows[0].ACCOUNT_ID, category_account_id: category.rows[0].ACCOUNT_ID, created_by: payload.userId || null, operation_id: { dir: oracledb.BIND_OUT, type: oracledb.NUMBER } }); await connection.commit(); return { operationId: inserted.outBinds.operation_id[0], operationNo: no, operationType, amount: operation.total, status: 'DRAFT' }; }); }
async function listExpenseIncome(payload = {}) { const limit = Math.min(Math.max(Number(payload.limit) || 100, 1), 500); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); return (await connection.execute(`select * from (select e.operation_id,e.operation_no,e.operation_type,e.operation_date,e.description_ar,e.amount,e.status_code,ca.account_code cash_account_code,ga.account_code category_account_code from onyx_expense_income e join onyx_account ca on ca.account_id=e.cash_account_id join onyx_account ga on ga.account_id=e.category_account_id where e.company_id=:company_id and e.branch_id=:branch_id and (:fiscal_year_id is null or e.fiscal_year_id=:fiscal_year_id) and (:operation_type is null or e.operation_type=:operation_type) order by e.operation_date desc,e.operation_id desc) where rownum <= :limit`, { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, fiscal_year_id: ctx.FISCAL_YEAR_ID || null, operation_type: payload.operationType || null, limit }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; }); }
