async function listStockMovements(payload = {}) { const limit = Math.min(Math.max(Number(payload.limit) || 100, 1), 500); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); return (await connection.execute(`select * from (select sm.movement_id,sm.movement_date,sm.movement_type,sm.quantity,sm.unit_cost,i.item_code,i.item_name_ar,w.warehouse_code,w.warehouse_name_ar,sm.invoice_id from onyx_stock_movement sm join onyx_item i on i.item_id=sm.item_id join onyx_warehouse w on w.warehouse_id=sm.warehouse_id where sm.company_id=:company_id and sm.branch_id=:branch_id and (:item_code is null or i.item_code=:item_code) order by sm.movement_date desc,sm.movement_id desc) where rownum <= :limit`, { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, item_code: payload.itemCode || null, limit }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; }); }
async function listInvoices(payload = {}) { const limit = Math.min(Math.max(Number(payload.limit) || 100, 1), 500); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); return (await connection.execute(`select * from (select i.invoice_id,i.invoice_no,i.invoice_type,i.invoice_date,i.subtotal,i.tax_amount,i.total_amount,i.paid_amount,i.outstanding_amount,i.status_code,i.currency_code,i.exchange_rate,c.code contact_code,c.name_ar contact_name from onyx_invoice i left join onyx_contact c on c.contact_id=i.contact_id where i.company_id=:company_id and i.branch_id=:branch_id and (:fiscal_year_id is null or i.fiscal_year_id=:fiscal_year_id) and (:invoice_type is null or i.invoice_type=:invoice_type) order by i.invoice_date desc,i.invoice_id desc) where rownum <= :limit`, { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, fiscal_year_id: ctx.FISCAL_YEAR_ID || null, invoice_type: payload.invoiceType || null, limit }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; }); }
async function reportContext(payload = {}) { const range = dateRange(payload); return { range, context: payload.context || {} }; }
async function trialBalanceReport(payload = {}) { const { range } = await reportContext(payload); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const result = await connection.execute(`select a.account_id,a.account_code,a.account_name_ar,a.account_type,nvl(a.opening_balance,0) opening_balance,nvl(sum(case when e.status_code='POSTED' and e.entry_date between to_date(:start_date,'YYYY-MM-DD') and to_date(:end_date,'YYYY-MM-DD') then l.debit else 0 end),0) total_debit,nvl(sum(case when e.status_code='POSTED' and e.entry_date between to_date(:start_date,'YYYY-MM-DD') and to_date(:end_date,'YYYY-MM-DD') then l.credit else 0 end),0) total_credit from onyx_account a left join onyx_journal_line l on l.account_id=a.account_id left join onyx_journal_entry e on e.entry_id=l.entry_id and e.company_id=:company_id and e.branch_id=:branch_id and e.fiscal_year_id=:fiscal_year_id where a.company_id=:company_id and a.active_flag=1 group by a.account_id,a.account_code,a.account_name_ar,a.account_type,a.opening_balance order by a.account_code`, { ...ctx, start_date: range.startDate, end_date: range.endDate }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const rows = result.rows.map(row => ({ ...row, BALANCE: Number(row.OPENING_BALANCE || 0) + Number(row.TOTAL_DEBIT || 0) - Number(row.TOTAL_CREDIT || 0) })); return { period: range, context: ctx, rows, totals: { debit: rows.reduce((s, r) => s + Number(r.TOTAL_DEBIT || 0), 0), credit: rows.reduce((s, r) => s + Number(r.TOTAL_CREDIT || 0), 0) } }; }); }
async function generalLedgerReport(payload = {}) { const { range } = await reportContext(payload); const accountCode = payload.accountCode ? String(payload.accountCode).trim() : null; return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); return { period: range, accountCode, rows: (await connection.execute(`select e.entry_id,e.entry_no,e.entry_date,e.description_ar,e.source_code,a.account_code,a.account_name_ar,l.line_description_ar,nvl(l.debit,0) debit,nvl(l.credit,0) credit from onyx_journal_entry e join onyx_journal_line l on l.entry_id=e.entry_id join onyx_account a on a.account_id=l.account_id where e.company_id=:company_id and e.branch_id=:branch_id and e.fiscal_year_id=:fiscal_year_id and e.status_code='POSTED' and e.entry_date between to_date(:start_date,'YYYY-MM-DD') and to_date(:end_date,'YYYY-MM-DD') and (:account_code is null or a.account_code=:account_code) order by e.entry_date,e.entry_id,l.line_id`, { ...ctx, start_date: range.startDate, end_date: range.endDate, account_code: accountCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows }; }); }
async function incomeStatementReport(payload = {}) { const { range } = await reportContext(payload); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const rows = (await connection.execute(`select a.account_type,a.account_code,a.account_name_ar,nvl(sum(l.debit),0) total_debit,nvl(sum(l.credit),0) total_credit from onyx_journal_entry e join onyx_journal_line l on l.entry_id=e.entry_id join onyx_account a on a.account_id=l.account_id where e.company_id=:company_id and e.branch_id=:branch_id and e.fiscal_year_id=:fiscal_year_id and e.status_code='POSTED' and e.entry_date between to_date(:start_date,'YYYY-MM-DD') and to_date(:end_date,'YYYY-MM-DD') and a.account_type in ('REVENUE','INCOME','EXPENSE','COST','COGS') group by a.account_type,a.account_code,a.account_name_ar order by a.account_code`, { ...ctx, start_date: range.startDate, end_date: range.endDate }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; const revenue = rows.filter(r => ['REVENUE','INCOME'].includes(r.ACCOUNT_TYPE)).reduce((s, r) => s + Number(r.TOTAL_CREDIT) - Number(r.TOTAL_DEBIT), 0); const expenses = rows.filter(r => ['EXPENSE','COST','COGS'].includes(r.ACCOUNT_TYPE)).reduce((s, r) => s + Number(r.TOTAL_DEBIT) - Number(r.TOTAL_CREDIT), 0); return { period: range, rows, totals: { revenue, expenses, profit: revenue - expenses } }; }); }
async function balanceSheetReport(payload = {}) { const { range } = await reportContext(payload); const trial = await trialBalanceReport(payload); const groups = trial.rows.reduce((acc, row) => { const type = String(row.ACCOUNT_TYPE || 'GENERAL').toUpperCase(); acc[type] = (acc[type] || 0) + Number(row.BALANCE || 0); return acc; }, {}); return { period: range, rows: trial.rows, totals: { assets: Math.abs(groups.ASSET || 0), liabilities: Math.abs(groups.LIABILITY || 0), equity: Math.abs(groups.EQUITY || 0), balancedDifference: (groups.ASSET || 0) - (groups.LIABILITY || 0) - (groups.EQUITY || 0) } }; }
async function salesPurchaseReport(payload = {}) { const { range } = await reportContext(payload); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const rows = (await connection.execute(`select i.invoice_type,i.currency_code,count(*) invoice_count,nvl(sum(i.subtotal),0) subtotal,nvl(sum(i.tax_amount),0) tax_amount,nvl(sum(i.total_amount),0) total_amount,nvl(sum(i.paid_amount),0) paid_amount,nvl(sum(i.outstanding_amount),0) outstanding_amount from onyx_invoice i where i.company_id=:company_id and i.branch_id=:branch_id and i.status_code='POSTED' and i.invoice_date between to_date(:start_date,'YYYY-MM-DD') and to_date(:end_date,'YYYY-MM-DD') group by i.invoice_type,i.currency_code order by i.invoice_type,i.currency_code`, { ...ctx, start_date: range.startDate, end_date: range.endDate }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; return { period: range, rows }; }); }
async function inventoryValuationReport(payload = {}) { const { range } = await reportContext(payload); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const rows = (await connection.execute(`select w.warehouse_code,w.warehouse_name_ar,i.item_code,i.item_name_ar,i.unit_name,nvl(b.quantity,0) quantity,nvl(b.average_cost,0) average_cost,nvl(b.quantity*b.average_cost,0) inventory_value from onyx_item_balance b join onyx_warehouse w on w.warehouse_id=b.warehouse_id join onyx_item i on i.item_id=b.item_id where w.company_id=:company_id and w.branch_id=:branch_id and b.quantity > 0 order by w.warehouse_code,i.item_code`, { ...ctx }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; return { period: range, rows, totalValue: rows.reduce((s, r) => s + Number(r.INVENTORY_VALUE || 0), 0) }; }); }
async function createReceivablePayment(payload = {}) { const payment = receivablesCore.buildPayment(payload); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const contact = await connection.execute('select contact_id,contact_type from onyx_contact where company_id=:company_id and code=:code', { company_id: ctx.COMPANY_ID, code: payment.contactCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const cash = await connection.execute('select account_id from onyx_account where company_id=:company_id and account_code=:code and active_flag=1', { company_id: ctx.COMPANY_ID, code: payment.cashAccountCode }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!contact.rows[0] || !cash.rows[0]) throw new Error('العميل أو المورد أو حساب النقدية غير موجود.'); const expectedType = payment.paymentType === 'RECEIPT' ? 'CUSTOMER' : 'VENDOR'; if (contact.rows[0].CONTACT_TYPE !== expectedType) throw new Error('نوع الجهة لا يتوافق مع نوع الدفعة.'); const expectedInvoice = payment.paymentType === 'RECEIPT' ? 'SALE' : 'PURCHASE'; const invoiceIds = []; for (const allocation of payment.allocations) { const invoice = await connection.execute('select invoice_id,invoice_type,contact_id,status_code,outstanding_amount from onyx_invoice where company_id=:company_id and branch_id=:branch_id and invoice_no=:invoice_no for update', { company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID, invoice_no: allocation.invoiceNo }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); const row = invoice.rows[0]; if (!row || row.INVOICE_TYPE !== expectedInvoice || Number(row.CONTACT_ID) !== Number(contact.rows[0].CONTACT_ID) || row.STATUS_CODE !== 'POSTED') throw new Error(`الفاتورة غير صالحة للتخصيص: ${allocation.invoiceNo}`); if (allocation.amount > Number(row.OUTSTANDING_AMOUNT) + 0.000001) throw new Error(`مبلغ التخصيص يتجاوز المتبقي للفواتير: ${allocation.invoiceNo}`); invoiceIds.push({ ...allocation, invoiceId: row.INVOICE_ID }); } const inserted = await connection.execute(`insert into onyx_ar_payment(company_id,branch_id,fiscal_year_id,contact_id,payment_type,payment_no,payment_date,cash_account_id,amount,allocated_amount,unapplied_amount,description_ar,status_code,created_by) values (:company_id,:branch_id,:fiscal_year_id,:contact_id,:payment_type,:payment_no,to_date(:payment_date,'YYYY-MM-DD'),:cash_account_id,:amount,:allocated_amount,:unapplied_amount,:description,'DRAFT',:created_by) returning payment_id into :payment_id`, { ...ctx, contact_id: contact.rows[0].CONTACT_ID, payment_type: payment.paymentType, payment_no: payment.paymentNo, payment_date: payment.paymentDate, cash_account_id: cash.rows[0].ACCOUNT_ID, amount: payment.amount, allocated_amount: payment.amount - payment.unappliedAmount, unapplied_amount: payment.unappliedAmount, description: payment.description, created_by: payload.userId || null, payment_id: { dir: oracledb.BIND_OUT, type: oracledb.NUMBER } }); const paymentId = inserted.outBinds.payment_id[0]; for (const allocation of invoiceIds) await connection.execute('insert into onyx_ar_allocation(payment_id,invoice_id,amount) values (:payment_id,:invoice_id,:amount)', { payment_id: paymentId, invoice_id: allocation.invoiceId, amount: allocation.amount }); await connection.commit(); return { paymentId, paymentNo: payment.paymentNo, status: 'DRAFT', allocatedAmount: payment.amount - payment.unappliedAmount, unappliedAmount: payment.unappliedAmount }; }); }
async function postReceivablePayment(payload = {}) { const paymentId = Number(payload.paymentId); if (!Number.isInteger(paymentId) || paymentId <= 0) throw new Error('رقم الدفعة غير صالح.'); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const payment = await connection.execute('select payment_id,payment_type,status_code from onyx_ar_payment where payment_id=:payment_id and company_id=:company_id and branch_id=:branch_id for update', { payment_id: paymentId, company_id: ctx.COMPANY_ID, branch_id: ctx.BRANCH_ID }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); if (!payment.rows[0] || payment.rows[0].STATUS_CODE !== 'DRAFT') throw new Error('الدفعة غير موجودة أو ليست مسودة.'); const allocations = await connection.execute('select a.invoice_id,a.amount,i.outstanding_amount from onyx_ar_allocation a join onyx_invoice i on i.invoice_id=a.invoice_id where a.payment_id=:payment_id for update', { payment_id: paymentId }, { outFormat: oracledb.OUT_FORMAT_OBJECT }); for (const row of allocations.rows) { if (Number(row.AMOUNT) > Number(row.OUTSTANDING_AMOUNT) + 0.000001) throw new Error('تغير رصيد إحدى الفواتير؛ أعد تحميل الدفعة.'); await connection.execute('update onyx_invoice set paid_amount=paid_amount+:amount,outstanding_amount=outstanding_amount-:amount,status_code=case when outstanding_amount-:amount <= 0.000001 then \'POSTED\' else status_code end where invoice_id=:invoice_id', { amount: row.AMOUNT, invoice_id: row.INVOICE_ID }); } await connection.execute('update onyx_ar_payment set status_code=\'POSTED\' where payment_id=:payment_id', { payment_id: paymentId }); await connection.commit(); return { paymentId, status: 'POSTED' }; }); }
async function listReceivablePayments(payload = {}) { const { range } = await reportContext(payload); return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); return (await connection.execute(`select p.payment_id,p.payment_no,p.payment_type,p.payment_date,p.amount,p.allocated_amount,p.unapplied_amount,p.status_code,c.code contact_code,c.name_ar contact_name from onyx_ar_payment p join onyx_contact c on c.contact_id=p.contact_id where p.company_id=:company_id and p.branch_id=:branch_id and p.payment_date between to_date(:start_date,'YYYY-MM-DD') and to_date(:end_date,'YYYY-MM-DD') order by p.payment_date desc,p.payment_id desc`, { ...ctx, start_date: range.startDate, end_date: range.endDate }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; }); }
async function receivablesAgingReport(payload = {}) { const asOfDate = String(payload.asOfDate || new Date().toISOString().slice(0, 10)).slice(0, 10); const contactType = String(payload.contactType || 'CUSTOMER').toUpperCase(); const invoiceType = contactType === 'VENDOR' ? 'PURCHASE' : 'SALE'; return withConnection(async connection => { const ctx = await modernContext(connection, payload.context || {}); const rows = (await connection.execute(`select i.invoice_id,i.invoice_no,i.invoice_date,i.due_date,i.invoice_type,i.total_amount,i.paid_amount,i.outstanding_amount,c.code contact_code,c.name_ar contact_name,case when i.due_date is null then 'NOT_DUE_DATE' when to_date(:as_of_date,'YYYY-MM-DD') <= i.due_date then 'CURRENT' when to_date(:as_of_date,'YYYY-MM-DD')-i.due_date <= 30 then 'DAYS_1_30' when to_date(:as_of_date,'YYYY-MM-DD')-i.due_date <= 60 then 'DAYS_31_60' when to_date(:as_of_date,'YYYY-MM-DD')-i.due_date <= 90 then 'DAYS_61_90' else 'DAYS_90_PLUS' end aging_bucket from onyx_invoice i join onyx_contact c on c.contact_id=i.contact_id where i.company_id=:company_id and i.branch_id=:branch_id and i.invoice_type=:invoice_type and i.status_code<>'VOID' and i.outstanding_amount > 0 order by i.due_date nulls last,i.invoice_date`, { ...ctx, as_of_date: asOfDate, invoice_type: invoiceType }, { outFormat: oracledb.OUT_FORMAT_OBJECT })).rows; const totals = rows.reduce((acc, row) => { const key = row.AGING_BUCKET; acc[key] = (acc[key] || 0) + Number(row.OUTSTANDING_AMOUNT || 0); acc.total = (acc.total || 0) + Number(row.OUTSTANDING_AMOUNT || 0); return acc; }, {}); return { asOfDate, contactType, rows, totals }; }); }
